#include "document_controls.h"
#include <cstdio>
#include <fstream>
#include <vector>
#include <cmath>
#include <limits>
using C=ux::DocumentControls;
#define CHECK(v) do{if(!(v))throw std::runtime_error(#v);}while(0)
namespace S=ib::sheets;
static C::Snapshot sample(){return {{"11111111-1111-4111-8111-111111111111",std::string(64,'a'),"pdf-source-v1",1},C::Format::Pdf,0,1000,{40,70,612,792},{},{12,600},false,false,false,false,"Sample",{}};}
// Controls are targets recorded at paint time (as on device): paint, then tap the target.
// A disabled or hidden control records no target; the tap lands on the sheet body.
static C::Command tap(C& c,int id,const C::Snapshot& s){static std::vector<std::uint32_t> pixels(1632*2160);c.paint({pixels,1620,2160,1632});auto r=c.target(id);if(r.empty())return c.hit(C::Panel.x0+6,C::Panel.y1-6,s);return c.hit((r.x0+r.x1)/2,(r.y0+r.y1)/2,s);}
static bool near(double a,double b){return std::abs(a-b)<1e-7;}
int main(int argc,char**argv){unsigned cases=0;auto test=[&](const char* name,auto f){f();++cases;std::printf("PASS %s\n",name);};try{
 test("pdf_preview_is_staged_apply_carries_immutable_binding",[]{auto s=sample();C c;CHECK(c.open(s));CHECK(tap(c,S::ZoomIn,s).action==C::Action::PreviewChanged);CHECK(c.previewPdf().zoom==1.25&&c.applied().pdf.zoom==1&&s.pdf.zoom==1);auto command=tap(c,S::Apply,s);CHECK(command.action==C::Action::ApplyPdf&&command.pdf.zoom==1.25&&command.binding==s.binding&&c.pending());CHECK(tap(c,S::Apply,s).refusal==C::Refusal::Busy&&tap(c,S::Cancel,s).refusal==C::Refusal::Busy);c.rejectApply();CHECK(!c.pending()&&tap(c,S::Cancel,s).action==C::Action::Cancel);});
 test("cancel_discards_pdf_preview_without_changing_applied_view",[]{auto s=sample();C c;CHECK(c.open(s));tap(c,S::RotateRight,s);tap(c,S::CropBase+(0)*2+1,s);CHECK(c.previewPdf().rotation==90&&c.previewPdf().crop);auto cancel=tap(c,S::Cancel,s);CHECK(cancel.action==C::Action::Cancel&&!c.active()&&c.previewPdf().rotation==0&&!c.previewPdf().crop&&c.applied().pdf.rotation==0);});
 test("zoom_pan_rotation_and_fit_stay_within_actual_planner_bounds",[]{auto s=sample();C c;CHECK(c.open(s));CHECK(tap(c,S::PanBase+(0),s).action==C::Action::None);for(int n=0;n<12;++n)CHECK(tap(c,S::ZoomIn,s).action==C::Action::PreviewChanged);CHECK(c.previewPdf().zoom==4&&tap(c,S::ZoomIn,s).action==C::Action::None);for(int n=0;n<30;++n){tap(c,S::PanBase+(3),s);tap(c,S::PanBase+(2),s);auto plan=reader::pdfview::plan(s.sourceBounds,c.previewPdf());CHECK(c.previewPdf().pan.x<=plan.maxPanX&&c.previewPdf().pan.y<=plan.maxPanY);}for(int n=0;n<4;++n){CHECK(tap(c,S::RotateRight,s).action==C::Action::PreviewChanged);CHECK(c.previewPdf().rotation==unsigned((n+1)*90)%360&&c.previewPdf().pan.x==0&&c.previewPdf().pan.y==0);}CHECK(tap(c,S::Fit,s).action==C::Action::PreviewChanged&&c.previewPdf().zoom==1);});
 test("fit_width_fills_the_screen_width_from_the_top",[]{auto s=sample();C c;CHECK(c.open(s));for(int n=0;n<6;++n){tap(c,S::CropBase+(0)*2+1,s);tap(c,S::CropBase+(1)*2+1,s);}
  CHECK(tap(c,S::FitWidth,s).action==C::Action::PreviewChanged);auto v=c.previewPdf();auto p=reader::pdfview::plan(s.sourceBounds,v);CHECK(v.zoom>1.1&&v.zoom<=4&&near(v.pan.y,p.maxPanY)&&v.pan.x==0&&p.maxPanY>0);
  const auto crop=*v.crop;CHECK(std::abs(crop.width*p.scale-reader::pdfview::Width)<0.01);CHECK(tap(c,S::FitWidth,s).action==C::Action::None);CHECK(tap(c,S::Fit,s).action==C::Action::PreviewChanged&&c.previewPdf().zoom==1);});
 test("blank_scan_crop_margins_preserve_nonzero_source_origin",[]{auto s=sample();C c;CHECK(c.open(s));for(unsigned edge=0;edge<4;++edge)CHECK(tap(c,S::CropBase+(edge)*2+1,s).action==C::Action::PreviewChanged);auto crop=*c.previewPdf().crop;CHECK(near(crop.x,40+612*.02)&&near(crop.y,70+792*.02)&&near(crop.width,612*.96)&&near(crop.height,792*.96));auto p=reader::pdfview::plan(s.sourceBounds,c.previewPdf());CHECK(p.visibleSource.x>=crop.x-1e-7);CHECK(tap(c,S::CropReset,s).action==C::Action::PreviewChanged&&!c.previewPdf().crop);});
 test("go_to_page_1000_is_paginated_and_requires_apply",[]{auto s=sample();C c;CHECK(c.open(s));tap(c,S::TabBase+2,s);CHECK(c.tab()==C::Tab::Pages&&c.firstVisiblePage()==0);tap(c,S::PageFirst+(3),s);CHECK(c.firstVisiblePage()==996&&c.pageForCell(3)==999&&c.pageForCell(4)==-1);CHECK(tap(c,S::PageCellBase+(3),s).action==C::Action::PreviewChanged&&c.selectedPage()==999&&c.applied().page==0);auto go=tap(c,S::Apply,s);CHECK(go.action==C::Action::JumpPage&&go.targetPage==999&&go.binding==s.binding);});
 test("partial_page_grid_and_first_previous_next_last_bounds",[]{auto s=sample();s.pages=27;C c;CHECK(c.open(s));tap(c,S::TabBase+2,s);CHECK(tap(c,S::PageFirst+(1),s).action==C::Action::None);tap(c,S::PageFirst+(2),s);CHECK(c.firstVisiblePage()==12);tap(c,S::PageFirst+(2),s);CHECK(c.firstVisiblePage()==24&&c.pageForCell(2)==26&&c.pageForCell(3)==-1);CHECK(tap(c,S::PageCellBase+(3),s).action==C::Action::None);CHECK(tap(c,S::PageFirst+(2),s).action==C::Action::None);tap(c,S::PageFirst+(1),s);CHECK(c.firstVisiblePage()==12);tap(c,S::PageFirst+(0),s);CHECK(c.firstVisiblePage()==0);});
 test("bookmark_chips_select_page_and_go_to_page_jumps",[]{auto s=sample();s.bookmarks={{12,false},{987,true}};C c;CHECK(c.open(s));tap(c,S::TabBase+2,s);
  CHECK(tap(c,S::BookmarkBase+(1),s).action==C::Action::PreviewChanged&&c.selectedPage()==987&&c.firstVisiblePage()==984);auto go=tap(c,S::Apply,s);CHECK(go.action==C::Action::JumpPage&&go.targetPage==987);
  C d;CHECK(d.open(s));tap(d,S::TabBase+2,s);CHECK(tap(d,S::BookmarkBase+(2),s).action==C::Action::None&&d.selectedPage()==0);});
 test("page_jump_does_not_apply_hidden_staged_zoom",[]{auto s=sample();C c;CHECK(c.open(s));tap(c,S::ZoomIn,s);tap(c,S::TabBase+2,s);tap(c,S::PageCellBase+(5),s);auto go=tap(c,S::Apply,s);CHECK(go.action==C::Action::JumpPage&&go.targetPage==5&&go.pdf.zoom==s.pdf.zoom);});
 test("stale_document_page_layout_epoch_or_applied_settings_rejected",[]{for(unsigned field=0;field<5;++field){auto s=sample();C c;CHECK(c.open(s));if(field==0)s.binding.document="changed";if(field==1)s.binding.page="changed";if(field==2)s.binding.layout="changed";if(field==3)++s.binding.epoch;if(field==4)s.pdf.zoom=2;CHECK(tap(c,S::ZoomIn,s).refusal==C::Refusal::Stale&&c.previewPdf().zoom==1);CHECK(tap(c,S::Apply,s).action==C::Action::None);}});
 test("contact_blocks_all_busy_allows_cancel_only",[]{auto s=sample();C c;CHECK(c.open(s));s.contact=true;CHECK(tap(c,S::Cancel,s).refusal==C::Refusal::Busy&&c.active());CHECK(tap(c,S::TabBase+2,s).refusal==C::Refusal::Busy);s.contact=false;s.busy=true;CHECK(tap(c,S::ZoomIn,s).refusal==C::Refusal::Busy);CHECK(tap(c,S::Cancel,s).action==C::Action::Cancel&&!c.active());});
 test("legacy_pinning_blocks_view_changes_not_page_selection",[]{auto s=sample();s.legacyInkPins=true;C c;CHECK(c.open(s));CHECK(tap(c,S::ZoomIn,s).action==C::Action::None);CHECK(tap(c,S::CropBase+(0)*2+1,s).action==C::Action::None);CHECK(tap(c,S::Apply,s).action==C::Action::None);tap(c,S::TabBase+2,s);tap(c,S::PageCellBase+(1),s);CHECK(tap(c,S::Apply,s).action==C::Action::JumpPage);s.format=C::Format::Epub;s.binding.layout="epub-fixed-600-800-12";C epub;CHECK(epub.open(s));tap(epub,S::TabBase+1,s);CHECK(tap(epub,S::FontMore,s).action==C::Action::None&&epub.previewEpub().fontSize==12);});
 test("epub_layout_signal_is_staged_and_bounded_not_fake_reflow",[]{auto s=sample();s.format=C::Format::Epub;s.binding.layout="epub-fixed-600-800-12";C c;CHECK(c.open(s));tap(c,S::TabBase+1,s);tap(c,S::FontMore,s);tap(c,S::LineMore,s);CHECK(c.previewEpub().fontSize==14&&c.previewEpub().lineWidth==650&&c.applied().epub.fontSize==12);auto apply=tap(c,S::Apply,s);CHECK(apply.action==C::Action::ApplyEpub&&apply.epub.fontSize==14&&apply.epub.lineWidth==650&&apply.binding==s.binding);C bounded;CHECK(bounded.open(s));tap(bounded,S::TabBase+1,s);for(int i=0;i<100;++i){tap(bounded,S::FontMore,s);tap(bounded,S::LineMore,s);}CHECK(bounded.previewEpub().fontSize==72&&bounded.previewEpub().lineWidth==4094);CHECK(tap(bounded,S::FontMore,s).action==C::Action::None);});
 test("epoch_update_invalidates_preview_and_old_taps",[]{auto s=sample();s.binding.epoch=3;C c;CHECK(c.open(s));tap(c,S::ZoomIn,s);auto busy=s;busy.busy=true;CHECK(c.update(busy)&&c.previewPdf().zoom==1.25);auto older=s;older.binding.epoch=2;CHECK(!c.update(older));auto changed=s;changed.pdf.zoom=2;CHECK(!c.update(changed));++changed.binding.epoch;CHECK(c.update(changed)&&c.previewPdf().zoom==2);CHECK(tap(c,S::Apply,s).refusal==C::Refusal::Stale);CHECK(c.takeDamage().x1==C::Panel.x1);});
 test("invalid_capacity_snapshots_and_outside_taps",[]{auto s=sample();C c;auto bad=s;bad.pages=1001;CHECK(!c.open(bad));bad=s;bad.sourceBounds.width=0;CHECK(!c.open(bad));CHECK(c.open(s));auto outside=c.hit(10,10,s);CHECK(outside.consumed&&outside.action==C::Action::Cancel&&!c.active()&&c.previewPdf().zoom==1);});
 test("all_panels_paint_within_fixed_rgb32_bounds",[&]{for(unsigned mode=0;mode<3;++mode){auto s=sample();if(mode==1){s.format=C::Format::Epub;s.binding.layout="epub-fixed-600-800-12";}C c;CHECK(c.open(s));if(mode==2)tap(c,S::TabBase+2,s);constexpr unsigned stride=1632;std::vector<std::uint32_t> pixels(stride*2160+16,0xffabcdef);CHECK(c.paint({pixels,1620,2160,stride}));bool changed=false;for(unsigned y=0;y<2160;++y)for(unsigned x=0;x<stride;++x){bool inside=x>=unsigned(C::Panel.x0)&&x<unsigned(C::Panel.x1)&&y>=unsigned(C::Panel.y0)&&y<unsigned(C::Panel.y1);if(!inside)CHECK(pixels[y*stride+x]==0xffabcdef);else changed|=pixels[y*stride+x]!=0xffabcdef;}CHECK(changed);for(unsigned n=stride*2160;n<pixels.size();++n)CHECK(pixels[n]==0xffabcdef);auto before=pixels;CHECK(!c.paint({std::span(pixels.data(),100),1620,2160,stride})&&pixels==before);if(argc==2){const char* suffix=mode==0?"-pdf.ppm":mode==1?"-epub.ppm":"-pages.ppm";std::ofstream out(std::string(argv[1])+suffix,std::ios::binary);out<<"P6\n1620 2160\n255\n";for(unsigned y=0;y<2160;++y)for(unsigned x=0;x<1620;++x){auto v=pixels[y*stride+x];out.put(char(v>>16));out.put(char(v>>8));out.put(char(v));}}}});
 std::printf("DOCUMENT_CONTROLS_TESTS_PASS cases=%u backend_calls=0 staged_apply=true UI_integration=targets\n",cases);return 0;
 }catch(const std::exception& e){std::fprintf(stderr,"DOCUMENT_CONTROLS_TEST_FAIL %s\n",e.what());return 1;}}
